<script>
(function(){
  var typeSelect=document.getElementById('filter-contact-type');
  var eventSelect=document.getElementById('filter-event');
  var blockedSelect=document.getElementById('filter-blocked');
  var buttons=document.querySelectorAll('[data-audience-type]');
  function syncButtons(){for(var i=0;i<buttons.length;i++){buttons[i].classList.toggle('selected',typeSelect&&buttons[i].getAttribute('data-audience-type')===typeSelect.value);}}
  for(var i=0;i<buttons.length;i++)buttons[i].addEventListener('click',function(){if(typeSelect)typeSelect.value=this.getAttribute('data-audience-type');if(blockedSelect)blockedSelect.value='no';syncButtons();if(eventSelect&&['buyer','guest','ticket_holder'].indexOf(this.getAttribute('data-audience-type'))!==-1&&!eventSelect.value)eventSelect.focus();});
  if(typeSelect)typeSelect.addEventListener('change',syncButtons);
  syncButtons();
})();
</script>
